const importedPoseIds = importedPoseRecords.map((record) => record.id)
const importedPoseMetadataOverrides = Object.fromEntries(importedPoseRecords.map((record) => [record.id, {
  categoryId: record.categoryId,
  categoryName: record.categoryName,
  name: record.name,
  tip: record.tip,
  description: record.description,
  badge: record.badge,
  guideImage: `/static/pose_pairs/${record.id.split('_')[0]}/${record.id}_contour.png`,
  gradient: record.gradient
}]))
const importedPoseSearchKeywordOverrides = Object.fromEntries(importedPoseRecords.map((record) => [record.id, record.searchKeywords]))
const importedPoseSceneKeywordOverrides = Object.fromEntries(importedPoseRecords.map((record) => [record.id, record.sceneKeywords]))
const importedGuideImageSizes = Object.fromEntries(importedPoseRecords.map((record) => [
  `/static/pose_pairs/${record.id.split('_')[0]}/${record.id}_contour.png`,
  { width: record.width, height: record.height }
]))

module.exports = {
  importedPoseIds,
  importedPoseMetadataOverrides,
  importedPoseSearchKeywordOverrides,
  importedPoseSceneKeywordOverrides,
  importedGuideImageSizes
}
